import math

def is_perfect_power(n, k):
    if n <= 0:
        return False
    if k <= 0:
        return False
    # Estimate the k-th root
    root = round(n**(1/k))
    # Check nearby integers due to floating point precision
    for r in range(max(1, root - 2), root + 3):
        if r**k == n:
            return True
    return False

C = 2051323

def check_A(A):
    results = {}
    for m in [1, 2, 3]:
        P_m_minus_1 = A**m + C
        exponent = m + 1
        is_power = is_perfect_power(P_m_minus_1, exponent)

        results[m] = {
            'P_m_minus_1': P_m_minus_1,
            'exponent': exponent,
            'is_power': is_power
        }
    return results

results_A2 = check_A(2)
results_A3 = check_A(3)
results_A4 = check_A(4)

print("A=2 results:", results_A2)
print("A=3 results:", results_A3)
print("A=4 results:", results_A4)

